import numpy as np
from rdkit import Chem
from rdkit.Chem import AllChem
from scipy.spatial.transform import Rotation
import json
els=[]; coords=[]; bonds=[]; labels={}
def atom(el,xyz,label=None):
 i=len(els); els.append(el); coords.append(np.array(xyz,dtype=float));
 if label: labels[label]=i
 return i
def fragment(smiles,seed=45):
 m=Chem.AddHs(Chem.MolFromSmiles(smiles)); AllChem.EmbedMolecule(m,randomSeed=seed)
 if AllChem.MMFFHasAllMoleculeParams(m): AllChem.MMFFOptimizeMolecule(m,maxIters=1000)
 else: AllChem.UFFOptimizeMolecule(m,maxIters=1000)
 return m,np.array(m.GetConformer().GetPositions())
def addfrag(m,xyz,skip=[]):
 ix={}
 for a in m.GetAtoms():
  if a.GetIdx() not in skip: ix[a.GetIdx()]=atom(a.GetSymbol(),xyz[a.GetIdx()])
 for b in m.GetBonds():
  if b.GetBeginAtomIdx() in ix and b.GetEndAtomIdx() in ix: bonds.append([ix[b.GetBeginAtomIdx()],ix[b.GetEndAtomIdx()],b.GetBondTypeAsDouble()])
 return ix
L=atom('Ir',[-1.7,0,0],'IrL'); R=atom('Ir',[1.7,0,0],'IrR')
m,p=fragment('c1nccn1-c1c(C)cc(C)cc1C')
print(Chem.MolToSmiles(Chem.RemoveHs(m)))
for a in m.GetAtoms():
 if a.GetIdx()<14: print(a.GetIdx(),a.GetSymbol(),[(n.GetIdx(),n.GetSymbol()) for n in a.GetNeighbors()])
# Match five-member ring to desired target using rigid alignment.
target=np.array([[-.67,1.75,0],[.67,1.75,0],[1.06,3.04,0],[-.04,3.86,0],[-1.13,3.06,0]])
p0=p[:5]; ca=p0.mean(0); cb=target.mean(0)
u,s,vt=np.linalg.svd((p0-ca).T@(target-cb)); rot=u@vt
if np.linalg.det(rot)<0: u[:,-1]*=-1; rot=u@vt
p=(p-ca)@rot+cb
skip=[n.GetIdx() for n in m.GetAtomWithIdx(0).GetNeighbors() if n.GetSymbol()=='H']
for t in [0,1]:
 q=p.copy()
 if t: q[:,:2]*=-1
 ix=addfrag(m,q,skip)
 labels['Cbridge'+str(t)]=ix[0]; labels['Nbridge'+str(t)]=ix[1]
 bonds+=[[L if t==0 else R,ix[0],1],[R if t==0 else L,ix[1],1]]
# trimethylphosphines: optimize free fragment, point methyl tripod away from metal
pm,pp=fragment('P(C)(C)C',55)
pp-=pp[0]
mean=pp[[1,2,3]].mean(0); src=mean/np.linalg.norm(mean)
for metal,sig,name in [(L,1,'PL'),(R,-1,'PR')]:
 dest=np.array([0.,0.,sig]); rot,_=Rotation.align_vectors(dest[None,:],src[None,:]); q=rot.apply(pp)+coords[metal]+dest*2.32
 ix=addfrag(pm,q); labels[name]=ix[0]; bonds.append([metal,ix[0],1])
# CO
for metal,sig,name in [(L,-1,'COL'),(R,1,'COR')]:
 c=atom('C',coords[metal]+[0,0,sig*1.90],name); o=atom('O',coords[c]+[0,0,sig*1.15]); bonds.extend([[metal,c,1],[c,o,3]])
# Methyl ligand, three C-H directions tetrahedral away from Ir
c=atom('C',coords[L]+[-2.12,0,0],'Me'); bonds.append([L,c,1])
for phi in np.radians([0,120,240]):
 h=atom('H',coords[c]+1.095*np.array([-1/3,np.sqrt(8/9)*np.cos(phi),np.sqrt(8/9)*np.sin(phi)])); bonds.append([c,h,1])
i=atom('I',coords[R]+[2.68,0,0],'I'); bonds.append([R,i,1])
coords=np.array(coords)
def write(path):
 with open(path,'w') as f:
  f.write(f'{len(els)}\nDinuclear iridium complex with two C,N-bridging N-mesitylimidazolyl ligands; angstrom\n')
  for el,pt in zip(els,coords): f.write(el+' '+' '.join(f'{x:.9f}' for x in pt)+'\n')
write('initial.xyz')
json.dump({'elements':els,'bonds':bonds,'labels':labels},open('topology.json','w'),indent=2)
print('Atoms',len(els),'labels',labels)
print('Formula',dict((e,els.count(e)) for e in set(els)))
